import React from 'react';
import { Link } from 'react-router-dom';
import './DrawerMenu.css'; // Crie um arquivo CSS para os estilo

const DrawerMenu = () => {
  console.log("DrawerMenu renderizado");
  
  return (
    <div style={{ width: '250px', background: '#ccc', padding: '10px', position: 'fixed', height: '100%' }}>
      <h2>Menu</h2>
      <ul style={{ listStyleType: 'none', padding: 0 }}>
        <li><Link to="/">Cadastro</Link></li>
        <li><Link to="/detalhes">Detalhes</Link></li>
      </ul>
    </div>
  );
};

export default DrawerMenu;
